          out.push({ name: name, role: role, hours: getDetailEmployeeHours(rule, ruleId, dateKey, name),
            clockedIn: window.TipOutAttendanceLabel.inspect(name,dateKey).status !== 'absent', orderCount: fact ? fact.orders.length : 0 });
