    function genDayData(dateKey, poolRules, ruleSalt) {
      if (window.TipOutDatePoolView && TipOutDatePoolView.buildDayData) {
        return TipOutDatePoolView.buildDayData(dateKey, poolRules, ruleSalt);
      }
      var parts = dateKey.split('-');
      var extra = 0;
      if (ruleSalt != null && ruleSalt !== '') {
        var rs = String(ruleSalt);
        for (var si = 0; si < rs.length; si++) extra = (extra * 31 + rs.charCodeAt(si)) % 100000;
      }
      var seed = parts.reduce(function(a, b) { return a * 31 + parseInt(b, 10); }, 0) + extra;
      var rng = seedRandom(seed);
      var dow = new Date(dateKey + 'T00:00:00').getDay();
      var wb = (dow === 5 || dow === 6) ? 1.4 : 1.0;
      var sales = +((3800 + rng() * 4400) * wb).toFixed(2);
      var tips = +((650 + rng() * 700) * wb).toFixed(2);
      var surcharge = +((120 + rng() * 180) * wb).toFixed(2);
      var manual = +((80 + rng() * 170) * wb).toFixed(2);
      var custom = 0;
      var pool = 0;
      var poolByRule = {};
      var salesCount = 0, tipsCount = 0, surchargeCount = 0;
      (poolRules || []).forEach(function(pr) {
        if (pr.type === 'sales') salesCount++;
        else if (pr.type === 'tips') tipsCount++;
        else if (pr.type === 'surcharge') surchargeCount++;
      });
      var demoEmployees = [
        { name: 'ServerA', role: 'Server', salesAmount: +(sales * 0.45).toFixed(2) },
        { name: 'BartenderB', role: 'Bartender', salesAmount: +(sales * 0.2).toFixed(2) },
        { name: 'OtherC', role: 'Cashier', salesAmount: +(sales * 0.35).toFixed(2) }
      ];
      (poolRules || []).forEach(function(pr) {
        var base = 0;
        var ruleAmt = 0;
        var rid = pr.id || pr.type;
        if (pr.type === 'personal_sales' && window.TipOutPersonalSalesDeduct && TipOutPersonalSalesDeduct.calcPersonalSalesPoolCard) {
          var card = TipOutPersonalSalesDeduct.calcPersonalSalesPoolCard(pr, demoEmployees);
          base = card.matchedSales || 0;
          ruleAmt = card.contribution || 0;
        } else {
          if (pr.type === 'sales') base = salesCount > 0 ? sales / salesCount : sales;
          else if (pr.type === 'tips') base = tipsCount > 0 ? tips / tipsCount : tips;
          else if (pr.type === 'surcharge') base = surchargeCount > 0 ? surcharge / surchargeCount : surcharge;
          else if (pr.type === 'manual') base = manual;
          else if (pr.type === 'custom') base = pr.amount != null ? pr.amount : custom;
          ruleAmt = +(base * (pr.pct != null ? pr.pct : 0) / 100).toFixed(2);
        }
        poolByRule[rid] = ruleAmt;
        pool += ruleAmt;
      });
      pool = +pool.toFixed(2);
      var poolBaseByRule = {};
      (poolRules || []).forEach(function(pr) {
        var rid = pr.id || pr.type;
        var amt = poolByRule[rid] || 0;
        var p = pr.pct != null ? pr.pct : 0;
        if (pr.type === 'personal_sales') {
          poolBaseByRule[rid] = (window.TipOutPersonalSalesDeduct && TipOutPersonalSalesDeduct.calcPersonalSalesPoolCard)
            ? (TipOutPersonalSalesDeduct.calcPersonalSalesPoolCard(pr, demoEmployees).matchedSales || 0)
            : (p > 0 ? +(amt * 100 / p).toFixed(2) : 0);
        } else {
          poolBaseByRule[rid] = p > 0 ? +(amt * 100 / p).toFixed(2) : 0;
        }
      });
      return { sales: sales, tips: tips, surcharge: surcharge, manual: manual, custom: custom, pool: pool, poolRules: poolRules, poolByRule: poolByRule, poolBaseByRule: poolBaseByRule, employeeSales: demoEmployees };
    }

    var detailAllRules = [];
    var detailTimeWindowResults = {};
    var detailTimeWindowErrors = {};
    function timeWeightReceivers(rule) {
      var out=[];
      function visit(rows) { (rows||[]).forEach(function(receiver){if((receiver.subReceivers||[]).length)visit(receiver.subReceivers);else out.push(receiver);}); }
      visit(rule.receivers);
      return out;
    }
    function buildTimeWeightInputs(rule,result) {
      var people=getRoleEmployeesForStore(rule.store), rows=[];
      window.TipOutEmployeeWeights.groups(rule.receivers,false).forEach(function(receiver,index) {
        (receiver.roles || []).forEach(function(role) { (people[role] || []).forEach(function(name) {
          var saved=result.weightOverrides && result.weightOverrides[index];
          var weight=window.TipOutEmployeeWeights.read(saved ? {employeeWeights:saved} : receiver,role,name);
          rows.push('<tr><td>'+escHtml(name)+'</td><td>'+escHtml(role)+'</td><td><input type="number" class="detail-time-weight-input" min="0" max="1000000" step="any" aria-label="员工权重" data-receiver="'+index+'" data-role="'+escHtml(role)+'" data-name="'+escHtml(name)+'" '+(result.weightSchemaVersion===1?'value="'+weight+'"':'value="" placeholder="—" data-weight-unrecorded="1"')+'></td></tr>');
        }); });
      });
      return '<table class="data-table detail-table"><thead><tr><th>接收员工</th><th>角色</th><th title="默认 1，仅影响当天本规则，按当前统计范围加权计算">员工权重</th></tr></thead><tbody>'+rows.join('')+'</tbody></table>';
    }
    function timeSavedWeights(rule,result,entry) {
      var weights=[];
      if(result.weightSchemaVersion===1) window.TipOutEmployeeWeights.groups(rule.receivers,false).forEach(function(receiver,index) {
        if((receiver.roles || []).indexOf(entry.role)<0) return;
        var saved=result.weightOverrides && result.weightOverrides[index];
        var value=window.TipOutEmployeeWeights.read(saved ? {employeeWeights:saved} : receiver,entry.role,entry.name);
        if(weights.indexOf(value)<0) weights.push(value);
      });
      return weights;
    }
    function onDetailTimeWeightInput(input) {
      var card=input.closest('.detail-card'), rule=detailWeightRule(card), scope=getDetailPayoutScope();
      try {
        TipOutDateState.assertDateWritable(scope.store,scope.dateKey);
        var copy=JSON.parse(JSON.stringify(rule)), targets=timeWeightReceivers(copy), overrides={};
        card.querySelectorAll('.detail-time-weight-input').forEach(function(field) {
          var index=field.getAttribute('data-receiver'),role=field.getAttribute('data-role'),name=field.getAttribute('data-name');
          if(field.getAttribute('data-weight-unrecorded')==='1') { field.value=window.TipOutEmployeeWeights.read(window.TipOutEmployeeWeights.groups(rule.receivers,false)[index],role,name); field.removeAttribute('data-weight-unrecorded'); }
          if (!overrides[index]) overrides[index]={};
          if (!overrides[index][role]) overrides[index][role]={};
          overrides[index][role][name]=window.TipOutEmployeeWeights.parse(field.value);
        });
        targets.forEach(function(target,index) { target.employeeWeights=overrides[index] || {}; });
        var result=TipOutTimeWindow.allocateRule(copy,TipOutScenarioSource.day(scope.dateKey,scope.store),scope.dateKey);
        result.weightOverrides=overrides;
        detailTimeWindowResults[String(rule.id)]=result;
        delete detailTimeWindowErrors[String(rule.id)];
        // Keep the focused weight input mounted: replacing its card can fire a
        // nested blur/change while the browser is still removing that card.
        var preview=document.createElement('div');
        preview.innerHTML=buildTimeWindowDetailCardHtml(rule,String(rule.id),result);
        var bodies=card.querySelectorAll('tbody'), nextBodies=preview.querySelectorAll('tbody');
        bodies[bodies.length-1].innerHTML=nextBodies[nextBodies.length-1].innerHTML;
        card.setAttribute('data-pool',result.poolAmount);
      } catch(error) { detailTimeWindowErrors[String(rule.id)]=error.message; showNotification(error.message,'error'); }
      markDetailDirty();
    }
    function buildTimeWindowDetailCardHtml(rule, rid, result) {
      var rows = result.lines.map(function(line) {
        var people = line.participants.filter(function(person) { return person.amount > 0; }).map(function(person) {
          return escHtml(person.name) + ' ' + money(person.amount)+(line.scope==='shift'?'（有效 '+Number(person.actualMinutes).toFixed(1)+' 分钟'+(rule.distribution==='hours'?'，计入 '+Number(person.allocationMinutes).toFixed(1)+' 分钟':'')+'）':'');
        }).join('、') || '无人符合参与资格';
        var sourceLabel = (line.source === 'manual' ? '手动上报' : '订单') + ' · ' + (line.sourceEmployeeName || line.sourceEmployeeId || '') +
          ' #' + String(line.sourceId || '').split(':').pop();
        if(line.scope==='shift') sourceLabel=line.shiftName+' · 排班表 · '+line.sourceEvents.length+' 笔来源；最低 '+line.minClockMinutes+' 分钟'+(rule.distribution==='hours'?'，计入上限 '+(line.maxClockMinutes||'不限')+' 分钟':'');
        return '<tr><td>' + escHtml(line.scope==='shift'?new Date(line.windowStartAt).toLocaleString('zh-CN',{timeZone:line.timeZone,hour12:false})+' — '+new Date(line.windowEndAt).toLocaleString('zh-CN',{timeZone:line.timeZone,hour12:false}):line.occurredAt.replace('T', ' ')) + '</td><td title="' + escHtml(line.sourceId) + '">' + escHtml(sourceLabel) +
          '</td><td>' + money(line.amount) + '</td><td>' + people + '</td><td>' + money(line.unallocated) + '</td></tr>';
      }).join('');
      return '<div class="card detail-card tipout-allocation-group" data-rule-id="' + escHtml(rid) + '" data-time-window="1" data-pool="' + result.poolAmount + '">' +
        '<div class="card-body detail-card-body-alloc" style="padding:16px"><strong>'+(result.scope==='shift'?'按班次统计并分配小费':'按打卡时段统计并分配小费')+'</strong>' +
        buildTimeWeightInputs(rule,result) +
        '<p class="field-desc">'+(result.scope==='shift'?'按当日排班表的班次和员工名单分配；参与员工需有班次内有效打卡。班次外小费不计入本规则，无合格员工的金额保留未分配。':'以订单支付完成或手动小费实际发生时间匹配有效打卡区间；区间采用左闭右开。未匹配金额保留为未分配。')+'</p>' +
        '<div class="detail-employee-wrap"><table class="data-table detail-table"><thead><tr><th>发生时间</th><th>来源</th><th>入池金额</th><th>接收员工</th><th>未分配</th></tr></thead><tbody>' +
        (rows || '<tr><td colspan="5">当日没有符合计算条件的小费事件</td></tr>') + '</tbody></table></div></div></div>';
    }
    var detailSelectedRuleIds = [];
