    function toggleMultiSelect(id) {
      const el = document.getElementById(id);
      if (!el) return;
      document.querySelectorAll('.multi-select.open').forEach(ms => {
        if (ms.id !== id) ms.classList.remove('open');
      });
      el.classList.toggle('open');
    }

    function removeMultiTag(e, selectId, value) {
      e.stopPropagation();
      const container = document.getElementById(selectId);
      if (!container) return;
      const checkboxes = container.querySelectorAll('input[type="checkbox"]');
      for (var i = 0; i < checkboxes.length; i++) {
        if (checkboxes[i].value === value) {
          checkboxes[i].checked = false;
          break;
        }
      }
      refreshMultiTags(selectId);
    }

    function refreshMultiTags(selectId) {
      const container = document.getElementById(selectId);
      if (!container) return;
      const tagsEl = container.querySelector('.multi-select-tags');
      if (!tagsEl) return;
      const checked = Array.from(container.querySelectorAll('input[type="checkbox"]:checked')).filter(function(cb) {
        return !cb.classList.contains('role-employee-select-all-cb');
      });
      const placeholder = (container.dataset && container.dataset.placeholder) || '请选择角色';
      tagsEl.innerHTML = '';
      if (checked.length === 0) {
        tagsEl.innerHTML = '<span class="multi-select-placeholder">' + placeholder + '</span>';
        return;
      }
      checked.forEach(function(cb) {
        const tag = document.createElement('span');
        tag.className = 'multi-select-tag';
        const labelText = cb.getAttribute('data-tag-label') || cb.value;
        const isShiftMulti = cb.getAttribute('data-tag-multiline') === '1';
        if (isShiftMulti) {
          tag.classList.add('shift-tag-multiline');
          const labelWrap = document.createElement('span');
          labelWrap.className = 'shift-tag-label';
          labelWrap.textContent = labelText;
          tag.appendChild(labelWrap);
        } else {
          tag.appendChild(document.createTextNode(labelText + '\\u00a0'));
        }
        const close = document.createElement('i');
        close.textContent = '×';
        close.style.cursor = 'pointer';
        close.addEventListener('click', function(ev) {
          ev.stopPropagation();
          cb.checked = false;
          refreshMultiTags(selectId);
          var msEl = document.getElementById(selectId);
          if (msEl && msEl.classList.contains('employee-condition-role-select')) {
            syncEmployeeConditionStaffFromRole(msEl);
          }
        });
        tag.appendChild(close);
        tagsEl.appendChild(tag);
      });
    }

